module.exports=[18622,(a,b,c)=>{b.exports=a.x("next/dist/compiled/next-server/app-page-turbo.runtime.prod.js",()=>require("next/dist/compiled/next-server/app-page-turbo.runtime.prod.js"))},56704,(a,b,c)=>{b.exports=a.x("next/dist/server/app-render/work-async-storage.external.js",()=>require("next/dist/server/app-render/work-async-storage.external.js"))},32319,(a,b,c)=>{b.exports=a.x("next/dist/server/app-render/work-unit-async-storage.external.js",()=>require("next/dist/server/app-render/work-unit-async-storage.external.js"))},20635,(a,b,c)=>{b.exports=a.x("next/dist/server/app-render/action-async-storage.external.js",()=>require("next/dist/server/app-render/action-async-storage.external.js"))},24725,(a,b,c)=>{b.exports=a.x("next/dist/server/app-render/after-task-async-storage.external.js",()=>require("next/dist/server/app-render/after-task-async-storage.external.js"))},43285,(a,b,c)=>{b.exports=a.x("next/dist/server/app-render/dynamic-access-async-storage.external.js",()=>require("next/dist/server/app-render/dynamic-access-async-storage.external.js"))},42602,(a,b,c)=>{"use strict";b.exports=a.r(18622)},87924,(a,b,c)=>{"use strict";b.exports=a.r(42602).vendored["react-ssr"].ReactJsxRuntime},72131,(a,b,c)=>{"use strict";b.exports=a.r(42602).vendored["react-ssr"].React},9270,(a,b,c)=>{"use strict";b.exports=a.r(42602).vendored.contexts.AppRouterContext},38783,(a,b,c)=>{"use strict";b.exports=a.r(42602).vendored["react-ssr"].ReactServerDOMTurbopackClient},35112,(a,b,c)=>{"use strict";b.exports=a.r(42602).vendored["react-ssr"].ReactDOM},36313,(a,b,c)=>{"use strict";b.exports=a.r(42602).vendored.contexts.HooksClientContext},18341,(a,b,c)=>{"use strict";b.exports=a.r(42602).vendored.contexts.ServerInsertedHtml},41146,a=>{"use strict";var b=a.i(64831);let c={name:"chevron-right",size:24,node:[["path",{d:"m9 18 6-6-6-6",key:"mthhwq"}]]};c.node;let d=(0,b.default)(c);a.s(["ChevronRight",0,d],41146)},93422,a=>{"use strict";var b=a.i(64831);let c={name:"scan-line",size:24,node:[["path",{d:"M3 7V5a2 2 0 0 1 2-2h2",key:"aa7l1z"}],["path",{d:"M17 3h2a2 2 0 0 1 2 2v2",key:"4qcy5o"}],["path",{d:"M21 17v2a2 2 0 0 1-2 2h-2",key:"6vwrx8"}],["path",{d:"M7 21H5a2 2 0 0 1-2-2v-2",key:"ioqczr"}],["path",{d:"M7 12h10",key:"b7w52i"}]]};c.node;let d=(0,b.default)(c);a.s(["ScanLine",0,d],93422)},87031,a=>{"use strict";let b=[{id:"invoice",title:"The invoice that wasn’t.",category:"Investigation story",year:"Fictional training case",subtitle:"One changed account number. Five decisions that matter.",fictional:!0,difficulty:"Start here",summary:"At 10:14, a finance officer receives a routine-looking payment update. By 10:27, the money is gone. Follow the evidence from the first call to a court-ready explanation.",story:["Maya, a fictional accounts officer at Northstar Studio, receives an email that appears to come from a long-standing supplier. It says their bank is undergoing an audit and asks her to use a new beneficiary account. The message is polite, the logo is correct, and the invoice number matches an outstanding order. Nothing about the request looks technically sophisticated.","Maya pays at 10:27. A call to the supplier’s usual contact reveals that no account change was requested. The team now has a running laptop, an email, a bank reference, and a rapidly moving payment trail. The first decision is not which hacking tool to open: it is how to stop further loss while preserving the original records and contacting the bank through an independently verified channel.","The investigator preserves the raw message and discovers that the visible supplier name conceals a different sending domain. SPF passes for that different domain, which is not proof that the real supplier authorized the request. A mailbox audit record later shows a new sign-in and a forwarding rule. Those observations support a compromise hypothesis, but the team still needs to connect the account, device, payment, and human actions.","The final exercise is deliberately restrained. The class can establish a message-and-payment sequence and identify missing records. It cannot declare a named person guilty merely from a domain, an IP address, or a model score. A useful report states the supported findings, preserves the uncertainty, and identifies the lawful next collection step."],timeline:[{date:"09:58",event:"Synthetic sign-in record shows a new session for the supplier mailbox."},{date:"10:14",event:"Changed-bank instruction arrives with a familiar invoice number."},{date:"10:27",event:"Maya authorizes the fictional payment."},{date:"10:42",event:"Independent call-back confirms the supplier did not request the change."}],issue:"Was the payment induced by personation or a compromised account, and which records reliably connect the events?",holding:"Training conclusion: preserve the raw email and payment trail, verify out of band, and investigate account control. Authentication results alone do not prove legitimacy.",lessons:["Urgency is a process risk, not proof of authorization.","Preserve the original message and full headers.","A pass for a different domain is not supplier approval.","Connect account, device, and payment evidence without overclaiming.","Use BSA section 63 for the actual submitted output."],questions:["Which evidence would distinguish mailbox compromise from a deceptive but legitimate account?","What should be preserved before the laptop is rebuilt?","How would you explain the difference between email authentication and payment authorization?"],sources:["itact","bns","bsa","cybercrime"],topics:["1.5","2.6","2.10","3.11"]},{id:"shreya",title:"A post, a prosecution, and free expression",category:"Landmark judgment",year:"2015",subtitle:"Shreya Singhal v. Union of India",fictional:!1,difficulty:"Law & rights",summary:"The Supreme Court examined section 66A and the intermediary framework, distinguishing discussion, advocacy, and incitement.",story:["Public interest litigation challenged arrests and prosecutions connected with online expression under section 66A of the IT Act. The petitions raised the provision’s breadth and the chilling effect of vague criminal restrictions on speech.","The Court distinguished discussion, advocacy, and incitement in its free-speech analysis. It held section 66A unconstitutional, finding that the provision did not fit the constitutionally permissible restriction framework for the relevant public-order analysis.","The decision also addressed intermediary liability and interpreted actual knowledge in the context of court orders or appropriate government notification. Later rules must be read with the statutory framework and the judgment, not as a license to disregard it."],timeline:[{date:"2012",event:"Arrests and controversy bring section 66A under public scrutiny."},{date:"2015",event:"Supreme Court decides the constitutional challenges."},{date:"Later years",event:"Official guidance addresses discontinuation of prosecutions under the invalidated provision."}],issue:"Whether section 66A validly restricted expression and how intermediary safe harbour should be understood.",holding:"Section 66A was struck down. The decision is a central authority on expression and intermediary liability, not a declaration that all online conduct is immune from prosecution.",lessons:["Read the actual holding, not a social-media summary.","Vagueness and overbreadth matter in penal restrictions.","Other valid offences may still apply to unlawful conduct.","Check current rules and later judgments for operational duties.","Do not use section 66A as a current charge."],questions:["Why is a printed bare Act not always a complete statement of current law?","How does the judgment distinguish expression from unlawful conduct?","What records would you keep of a platform’s legal basis for removal?"],sources:["shreya","itact","it2026"],topics:["1.2","1.3","1.11"]},{id:"anvar",title:"The election record that had to be proved",category:"Landmark judgment",year:"2014",subtitle:"Anvar P.V. v. P.K. Basheer",fictional:!1,difficulty:"Electronic evidence",summary:"Electronic output required the special proof route under section 65B, rather than an unrestricted general secondary-evidence route.",story:["An election dispute involved recordings and media relied on to support allegations. The evidential question was not simply whether the material sounded persuasive: it was how electronic output could legally be proved.","The Supreme Court emphasized the special provision for electronic records. Anvar held that the general secondary-evidence rules could not bypass the conditions of section 65B for the output concerned.","The decision generated practical questions about certificates, original devices, and parties unable to control a source. Later decisions clarified the position. Today, the reasoning must be read with BSA section 63 and its Schedule rather than copied into a current filing unchanged."],timeline:[{date:"2014",event:"Supreme Court delivers the Anvar decision."},{date:"2018",event:"Shafhi Mohammad introduces a relaxation later disapproved."},{date:"2020",event:"Arjun Panditrao clarifies the certification position."},{date:"2024",event:"BSA section 63 becomes the applicable new statutory framework."}],issue:"The route for proving electronic-record contents under the former Evidence Act.",holding:"The special section 65B route governed the electronic output concerned. Current analysis must use the BSA and applicable precedent.",lessons:["Identify the exact output being tendered.","Distinguish original-device production from copied output.","Preserve source and process information early.","Read later clarifying judgments.","Update the certificate to the current Schedule."],questions:["Why does admissibility require more than relevance?","What changed between the old certificate and BSA section 63?","How would you document a multi-device source?"],sources:["anvar","arjun","bsa"],topics:["2.9","2.10"]},{id:"arjun",title:"Who can certify the record?",category:"Landmark judgment",year:"2020",subtitle:"Arjun Panditrao Khotkar v. Kailash Kushanrao Gorantyal",fictional:!1,difficulty:"Electronic evidence",summary:"A Constitution Bench clarified section 65B certification and the distinction between producing an original device and proving electronic output.",story:["The dispute concerned electronic material and the steps needed to rely on it. The Court reviewed the earlier authorities, including Anvar and Shafhi Mohammad, to resolve uncertainty about certification.","The decision clarified the certificate requirement for the output route and disapproved the relaxation in Shafhi. It also explained the different position where the original device itself is produced, and discussed steps a party may take to obtain a necessary certificate from a source it does not control.","For present practice, the key is not to replace every occurrence of “65B” with “63”. The BSA has a prescribed Schedule, party and expert portions, and express hash particulars. The underlying questions of source, control, process, and truthful certification remain essential."],timeline:[{date:"2014",event:"Anvar states the special electronic-proof approach."},{date:"2018",event:"Shafhi creates uncertainty through a relaxation."},{date:"2020",event:"The Constitution Bench clarifies the position."},{date:"2024",event:"The BSA introduces the current scheduled certificate."}],issue:"When a certificate is required and how the electronic-evidence proof framework should be applied.",holding:"Arjun clarified the former section 65B position, including the original-device distinction and disapproval of Shafhi’s relaxation. Read it with the current BSA text.",lessons:["Do not treat screenshots as automatically admissible or inadmissible.","Identify the form of evidence actually submitted.","Use lawful steps to obtain third-party certification.","Record the source and production process.","Do not reuse the old one-signature form unchanged."],questions:["How does control of the source affect preparation?","Why is the output-versus-original distinction important?","What should a current Part A and Part B worksheet contain?"],sources:["arjun","bsa","bsa-schedule"],topics:["2.9","2.10","4.12"]},{id:"privacy",title:"Privacy is not an optional extra",category:"Landmark judgment",year:"2017",subtitle:"K.S. Puttaswamy v. Union of India",fictional:!1,difficulty:"Law & rights",summary:"A nine-judge bench recognized privacy as a fundamental right, shaping how digital investigative powers must be understood.",story:["The case arose in a context that included challenges to the Aadhaar framework and broader questions about informational privacy. A nine-judge bench examined whether the Constitution protected privacy.","The Court recognized privacy as a fundamental right and discussed its relationship with life, liberty, autonomy, dignity, and other freedoms. The judgment did not make every restriction unconstitutional; it required a proper legal and constitutional basis.","For investigators, the practical lesson is to connect each collection action to authority, legitimate purpose, proportionality, and safeguards. A device contains far more than the relevant message. Scope, minimization, secure handling, and accountable access are not optional additions to a technically successful acquisition."],timeline:[{date:"2017",event:"Nine-judge bench recognizes the fundamental right to privacy."},{date:"2018 onward",event:"Related proceedings address the Aadhaar framework."},{date:"2023",event:"The DPDP Act creates a separate statutory personal-data framework."}],issue:"Constitutional protection of privacy and the framework for evaluating state interference.",holding:"Privacy is a fundamental right. The legality and justification of a particular restriction require analysis of the applicable right, measure, and safeguards.",lessons:["Authority comes before technical convenience.","Collect within a defined and relevant scope.","Protect unrelated personal information.","Record the purpose and proportionality of material decisions.","Distinguish constitutional principles from a specific statute’s operational rules."],questions:["How would you narrow a cloud-record request?","What should a device examination plan say about unrelated data?","Why does public availability not settle every privacy question?"],sources:["privacy","constitution","dpdp"],topics:["1.3","2.3","2.12"]},{id:"stuxnet",title:"When code reached the physical world",category:"Cyber-physical case",year:"2010",subtitle:"Stuxnet and industrial control systems",fictional:!1,difficulty:"Advanced concepts",summary:"A sophisticated worm targeted industrial control environments, demonstrating how cyber operations could produce physical effects.",story:["Stuxnet attracted attention because it affected industrial control systems rather than merely stealing documents or defacing websites. Public technical reporting examined its propagation, targeting, and interaction with Siemens control environments.","The case illustrates the importance of asset inventory, segmentation, trusted engineering workflows, removable-media controls, and monitoring of process behavior. A normal-looking IT event can have operational consequences when systems are connected.","Attribution and the legal characterization of the operation have been debated in public sources. A classroom analysis should distinguish documented technical behavior from contested claims about sponsorship, intent, and international-law thresholds. The case is not a lab instruction to interact with industrial systems."],timeline:[{date:"2010",event:"Public discovery and technical analysis of Stuxnet."},{date:"2010–2011",event:"Industrial-security advisories and mitigation guidance develop."},{date:"Later research",event:"Technical and policy analysis continues; attribution claims remain distinct from proof in a court."}],issue:"How cyber operations can affect industrial processes and why safety, evidence, and response must be coordinated.",holding:"Technical lesson: cyber-physical investigation requires process context, controlled safety measures, and careful separation of technical findings from disputed attribution.",lessons:["Map IT and operational-technology dependencies.","Do not treat all system failures as malware or all malware as terrorism.","Preserve engineering and process context.","Coordinate safety and evidence decisions.","Use qualified language for attribution and legal thresholds."],questions:["What additional evidence is needed in a cyber-physical incident?","Why could an immediate rebuild be unsafe or destroy evidence?","How do you separate technical observation from a political claim?"],sources:["stuxnet","nist-csf"],topics:["5.4","5.5","5.6"]},{id:"solarwinds",title:"The update everyone trusted",category:"Supply-chain incident",year:"2020",subtitle:"The SolarWinds Orion compromise",fictional:!1,difficulty:"Threat intelligence",summary:"A trusted software-update path became a route for compromise, showing why supply-chain evidence and follow-on activity must be analyzed separately.",story:["Organizations discovered that affected SolarWinds Orion builds could distribute malicious code through a trusted update mechanism. The incident raised immediate questions about which versions were present, which systems communicated with attacker infrastructure, and what subsequent access occurred.","CISA issued emergency mitigation guidance. The response required more than removing one file: investigators needed to consider identity, trust, cloud access, persistence, and the integrity of management systems.","The case demonstrates the value of build records, update provenance, authentication logs, endpoint telemetry, and provider cooperation. Presence of an affected product does not prove the same follow-on impact in every organization. Technical compromise, operational intrusion, and public attribution are different analytical layers."],timeline:[{date:"2020",event:"Compromise and investigation become public."},{date:"December 2020",event:"CISA issues Emergency Directive 21-01."},{date:"2021 onward",event:"Technical analysis, response guidance, and attribution discussions continue."}],issue:"How to investigate and respond to compromise delivered through trusted software and management relationships.",holding:"Defensive lesson: establish product exposure, investigate follow-on activity, protect identity and management trust, and avoid assuming uniform impact across victims.",lessons:["Inventory software and management dependencies.","Preserve build, deployment, and identity records.","Distinguish exposure from confirmed follow-on access.","Use coordinated containment and trusted recovery.","Keep attribution confidence separate from observed technique."],questions:["Which records connect an update to later account activity?","Why is removing the affected version alone insufficient?","What would you include in a supply-chain intelligence requirement?"],sources:["solarwinds","mitre","nist-ir"],topics:["5.1","5.3","5.6"]},{id:"voice",title:"The voice on the other end",category:"AI-enabled fraud",year:"2019",subtitle:"The reported UK cloned-voice transfer",fictional:!1,difficulty:"Emerging threats",summary:"Reporting described a fraud in which a cloned senior voice helped induce a transfer of about €220,000.",story:["A widely reported 2019 case involved a UK energy firm’s manager receiving a call that appeared to reproduce a senior executive’s voice. The request led to a transfer of approximately €220,000 to a supposed supplier.","The important lesson is not that human hearing became useless. It is that payment authorization should not depend only on a familiar voice, caller identity, or urgency. Independent call-back, dual approval, and beneficiary verification remain valuable even when deception is convincing.","Later reporting discussed other incidents, sometimes with different amounts and victims. Keep the 2019 case distinct from those later events. The technical details available in public reporting do not replace the original call records, bank trail, or evidence needed to attribute the operation."],timeline:[{date:"2019",event:"The reported cloned-voice request induces the transfer."},{date:"Later reporting",event:"The incident is discussed alongside separate deepfake-fraud cases."},{date:"2026",event:"Indian intermediary rules add specific synthetic-information duties, distinct from this UK incident."}],issue:"How AI-assisted impersonation can defeat informal trust cues and why process controls matter.",holding:"Practical lesson: use independent verification and payment controls; do not treat voice similarity or an AI-detector result as conclusive proof.",lessons:["Verify through a previously known contact channel.","Separate payment approval from perceived identity.","Preserve call, message, and beneficiary records.","Keep different reported incidents and amounts distinct.","Design controls that remain effective when deception succeeds."],questions:["Which control would have interrupted this payment?","What evidence would help attribute the call?","Why is a synthetic-media label not a complete fraud-prevention strategy?"],sources:["deepfake","it2026","nist-csf"],topics:["1.5","5.7","5.8"]},{id:"twitter",title:"The account was real. The request was not.",category:"Social-engineering case",year:"2020",subtitle:"The Twitter account-takeover incident",fictional:!1,difficulty:"Investigation & identity",summary:"Misuse of access to internal tools enabled high-profile accounts to publish a cryptocurrency scam, illustrating the gap between account authenticity and message legitimacy.",story:["In July 2020, prominent Twitter accounts published messages promoting a cryptocurrency payment scheme. The posts appeared on genuine accounts, making ordinary “check the profile” advice inadequate.","Public authorities described social engineering and misuse of internal access in the investigation and charges. The case shows why employee identity, privileged tools, approval paths, and audit logs are central to platform security.","For evidence handling, preserve the account posts, backend audit records, access approvals, and payment trail through lawful process. A verified badge or authentic account can establish where a message appeared, but not that the legitimate owner intended the request."],timeline:[{date:"15 July 2020",event:"High-profile accounts publish scam messages."},{date:"July 2020",event:"Platform containment and investigation proceed."},{date:"31 July 2020",event:"US authorities announce charges concerning the incident."}],issue:"How social engineering and privileged access can undermine trust in authentic accounts.",holding:"Investigative lesson: examine internal access and account-control records, not merely the public profile. The cited charges are allegations and procedural history, not a substitute for reviewing the final case outcome.",lessons:["A genuine account can be compromised.","Protect and monitor privileged internal tools.","Preserve access and approval logs.","Separate platform provenance from human intent.","Use precise language for charges, allegations, and findings."],questions:["What internal records would you request?","How would you explain account authenticity to a non-technical reader?","Which controls reduce the impact of a successful social-engineering attempt?"],sources:["twitter"],topics:["3.4","3.12","5.3"]}],c=Object.fromEntries(b.map(a=>[a.id,a]));a.s(["caseMap",0,c,"cases",0,b])},86389,a=>{"use strict";var b=a.i(64831);let c={name:"notebook-pen",size:24,node:[["path",{d:"M13.4 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-7.4",key:"re6nr2"}],["path",{d:"M2 6h4",key:"aawbzj"}],["path",{d:"M2 10h4",key:"l0bgd4"}],["path",{d:"M2 14h4",key:"1gsvsf"}],["path",{d:"M2 18h4",key:"1bu2t1"}],["path",{d:"M21.378 5.626a1 1 0 1 0-3.004-3.004l-5.01 5.012a2 2 0 0 0-.506.854l-.837 2.87a.5.5 0 0 0 .62.62l2.87-.837a2 2 0 0 0 .854-.506z",key:"pqwjuv"}]]};c.node;let d=(0,b.default)(c);a.s(["NotebookPen",0,d],86389)},30494,a=>{"use strict";var b=a.i(64831);let c={name:"folder-search",size:24,node:[["path",{d:"M10.7 20H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h3.9a2 2 0 0 1 1.69.9l.81 1.2a2 2 0 0 0 1.67.9H20a2 2 0 0 1 2 2v4.1",key:"1bw5m7"}],["path",{d:"m21 21-1.9-1.9",key:"1g2n9r"}],["circle",{cx:"17",cy:"17",r:"3",key:"18b49y"}]]};c.node;let d=(0,b.default)(c);a.s(["FolderSearch",0,d],30494)},88444,a=>{"use strict";var b=a.i(64831);let c={name:"printer",size:24,node:[["path",{d:"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2",key:"143wyd"}],["path",{d:"M6 9V3a1 1 0 0 1 1-1h10a1 1 0 0 1 1 1v6",key:"1itne7"}],["rect",{x:"6",y:"14",width:"12",height:"8",rx:"1",key:"1ue0tg"}]]};c.node;let d=(0,b.default)(c);a.s(["Printer",0,d],88444)},18783,a=>{"use strict";var b=a.i(64831);let c={name:"arrow-right",size:24,node:[["path",{d:"M5 12h14",key:"1ays0h"}],["path",{d:"m12 5 7 7-7 7",key:"xquz4c"}]]};c.node;let d=(0,b.default)(c);a.s(["ArrowRight",0,d],18783)},18688,a=>{"use strict";var b=a.i(64831);let c={name:"book-open",size:24,node:[["path",{d:"M12 5v16",key:"1f6ucr"}],["path",{d:"M20.001 19A2 2 0 0022 17V5a2 2 0 00-1.999-2L16 3.002A5 5 0 0012 5a5 5 0 00-4-2H4a2 2 0 00-2 2v12a2 2 0 001.999 2H8a5 5 0 014 2 5 5 0 014-2z",key:"1fyvmf"}]]};c.node;let d=(0,b.default)(c);a.s(["BookOpen",0,d],18688)},36280,a=>{"use strict";let b=[{id:"holt",title:"Cybercrime and Digital Forensics",authors:"Thomas J. Holt, Adam M. Bossler & Kathryn C. Seigfried-Spellar",publisher:"Routledge",year:"3rd edition · 2022",color:"navy",code:"CRIME / SOCIETY / TECHNOLOGY",url:"https://www.routledge.com/Cybercrime-and-Digital-Forensics-An-Introduction/Holt-Bossler-Seigfried-Spellar/p/book/9780367360078",description:"Start here for the human and social context of cybercrime, then connect offending patterns to investigation and evidence. The third edition contains 17 chapters.",editionNote:"Chapter titles follow the publisher’s third-edition listing. The explanations and study prompts below are original. Indian legal updates come from primary sources, not this 2022 text.",chapters:[{title:"1. Technology and Cybercrime",summary:"Distinguish computer-target and computer-enabled conduct. Build a vocabulary for actors, systems, and harms before selecting an investigative method.",topics:["1.1","1.5"]},{title:"2. Law Enforcement, Privacy, and Security in Dealing with Cybercrime",summary:"Compare institutional roles and the tension between investigative access and civil liberties. Translate the discussion into an Indian authority register.",topics:["1.8","2.1","2.3"]},{title:"3. Computer Hackers and Hacking",summary:"Examine hacking subcultures, authorization, and legal frameworks without treating technical curiosity as a single criminal category.",topics:["1.4","3.8"]},{title:"4. Malware and Automated Computer Attacks",summary:"Connect malware behavior to observable artifacts and response priorities. Separate the program’s function from attribution to an actor.",topics:["3.8","4.7"]},{title:"5. Digital Piracy and Intellectual Property Theft",summary:"Study the social and economic organization of unauthorized distribution, and distinguish the relevant legal interests from system intrusion.",topics:["1.4","2.5"]},{title:"6. Online Fraud",summary:"Trace deception, identity misuse, and payment inducement. Use the invoice case to practice an ingredient table and preservation plan.",topics:["1.5","3.11"]},{title:"7. Pornography, Image-Based Sexual Abuse, and Prostitution",summary:"Approach image-based harm through victim protection, legal distinctions, and sensitive evidence handling. Do not reproduce or circulate harmful material.",topics:["1.5","2.12"]},{title:"8. Child Sexual Exploitation Material Offenses",summary:"Understand the specialized legal and safeguarding framework. This course gives conceptual guidance only and contains no exploitative material or operational acquisition instructions.",topics:["1.6","2.12"]},{title:"9. Cyberbullying, Online Harassment, and Cyberstalking",summary:"Consider repetition, context, harm, and platform records. Compare the general Indian provisions without assuming every offensive post is stalking.",topics:["1.5","3.4"]},{title:"10. Online Extremism and Cyberterror",summary:"Separate extremist content, mobilization, and the narrower legal definition of terrorist conduct. Identify the evidence needed for intent and effects.",topics:["5.5"]},{title:"11. Cyberwarfare and Information Operations Online",summary:"Examine state interests, offensive and defensive operations, and information influence while keeping legal thresholds explicit.",topics:["5.4","5.6"]},{title:"12. Illicit Market Operations Online",summary:"Evaluate market claims, reputation, and transaction trails. Distinguish a public ledger observation from proof of address ownership.",topics:["3.6","5.1"]},{title:"13. Cybercrime and Criminological Theories",summary:"Use theory to form alternative explanations about offending and victimization, not to infer guilt from a profile.",topics:["1.3","5.3"]},{title:"14. Evolution of Digital Forensics",summary:"Connect the growth of digital evidence to method, process models, and the examiner’s responsibilities.",topics:["2.4","3.7"]},{title:"15. Acquisition and Examination of Forensic Evidence",summary:"Study preservation, imaging, examination, and reporting. Practise the integrity workflow, then update the legal references to the BSA.",topics:["2.6","4.4","4.5"]},{title:"16. Legal Challenges in Digital Forensic Investigations",summary:"Compare constitutional, admissibility, and expert-evidence issues. The book’s international treatment must be supplemented with current Indian law.",topics:["2.9","2.10","4.12"]},{title:"17. The Future of Cybercrime, Terror, and Policy",summary:"Evaluate emerging technologies through scenarios, uncertainty, and policy choices rather than prediction alone.",topics:["5.7","5.12"]}]},{id:"choo",title:"Cyber and Digital Forensic Investigations",authors:"Edited by Nhien-An Le-Khac & Kim-Kwang Raymond Choo",publisher:"Springer · Studies in Big Data 74",year:"2020",color:"teal",code:"LAW ENFORCEMENT / PRACTICE",url:"https://link.springer.com/book/10.1007/978-3-030-47131-6",description:"A practitioner-oriented collection spanning IoT, ransomware, CCTV, financial accounts, cloud services, mobile networks, Tor, and Bitcoin. Read it as a set of specialist investigations rather than a single universal procedure.",editionNote:"The publisher lists 12 chapters. Some editions combine related ransomware or PayPal chapters in their display; use the chapter titles in your own copy. This guide uses ten study sections covering those subjects.",chapters:[{title:"1. The Increasing Importance of Digital Forensics and Investigations",summary:"Frame the growing role of digital evidence in law enforcement, government, and commercial investigations.",topics:["2.1","2.5"]},{title:"2. Defending IoT Devices from Malware",summary:"Map device constraints, attack surfaces, and defensive evidence sources in connected environments.",topics:["3.8","5.7"]},{title:"3. Digital Forensic Investigation of Internet of Thing Devices",summary:"Use a model-based approach to identify evidence across devices, companion applications, and services.",topics:["2.5","3.10"]},{title:"4–5. Forensic Investigation of Ransomware Activities",summary:"Connect incident stages, artifacts, and response decisions. Separate containment from proof of initial access or actor identity.",topics:["3.8","4.7","5.3"]},{title:"6. CCTV Forensics in the Big Data Era",summary:"Consider time accuracy, video provenance, scale, and interpretation. A visible person or event still needs contextual verification.",topics:["2.4","2.6"]},{title:"7. Forensic Investigation of PayPal Accounts",summary:"Study financial-account records and the link between account control, transactions, and external corroboration. Platform interfaces and policies change.",topics:["2.5","3.11"]},{title:"8. Digital Forensic Approaches for Cloud Service Models",summary:"Compare evidence control in IaaS, PaaS, and SaaS. Build a tenant-and-provider source matrix before requesting acquisition.",topics:["3.12","2.12"]},{title:"9. LTE Network Security and Real-Time Data Extraction",summary:"Understand the specialist network context and distinguish research extraction methods from authorized forensic practice.",topics:["3.9","3.10"]},{title:"10. Towards an Automated Process to Categorise Tor’s Hidden Services",summary:"Evaluate automated classification, dataset limits, and the difference between a category prediction and an evidential finding.",topics:["3.6","5.11"]},{title:"11–12. The Bitcoin-Network Protocol from a Forensic Perspective; What Next?",summary:"Study public ledger observations and future directions. Address clustering does not by itself establish the human controller or criminal purpose.",topics:["3.6","5.12"]}]},{id:"advancements",title:"Advancements in Cybercrime Investigation and Digital Forensics",authors:"Edited by Chandra Singh, Amarnath Mishra & A. Harisha",publisher:"Apple Academic Press / CRC Press",year:"2024 copyright · published 2023",color:"ochre",code:"METHODS / MACHINE LEARNING",url:"https://www.routledge.com/Advancements-in-Cybercrime-Investigation-and-Digital-Forensics/Harisha-Mishra-Singh/p/book/9781774913031",description:"An 18-chapter research collection connecting Indian investigation challenges with recovery, mobile evidence, dark-web analysis, machine learning, and AI-assisted forensics.",editionNote:"Chapter order follows the publisher’s listing. The study explanations are original. Evaluate research methods and datasets rather than treating every reported result as operationally validated.",chapters:[{title:"1. Challenges to Cybercrime Reporting, Investigation, and Adjudication in India",summary:"Identify reporting, first-response, agency, technical, and jurisdictional barriers, then supplement the legal discussion with the post-2024 framework.",topics:["2.1","2.12"]},{title:"2. A Comprehensive Review on Digital Forensics Intelligence",summary:"Connect forensic examination with intelligence requirements and cross-source evaluation.",topics:["3.7","5.1"]},{title:"3. Security Mechanisms for Information Protection and Transmission over Open Networks",summary:"Review protection mechanisms and the traces they create or limit in network investigation.",topics:["3.9","4.8"]},{title:"4. Wearable Devices and Forensic Investigation",summary:"Map wearable, companion-app, and cloud evidence, including synchronization and location uncertainty.",topics:["2.5","3.10"]},{title:"5. Combating Cybercrimes with Digital Forensics",summary:"Connect investigative method to the legal and operational context of a case.",topics:["2.2","3.7"]},{title:"6. Clustering and Classification of Digital Forensic Data",summary:"Study machine-learning and data-mining approaches, feature choices, and evaluation limits.",topics:["5.9","5.11"]},{title:"7. Digital Forensic Investigation: Ontology, Methodology, and Technological Advancement",summary:"Examine process models and how tools fit a defensible investigative method.",topics:["3.7","4.1"]},{title:"8. Data Breach Fraudulence and Preventive Measures in E-Commerce Platforms",summary:"Trace breach and fraud pathways through accounts, transactions, and platform controls.",topics:["1.5","5.7"]},{title:"9. An Approach to Data Recovery from Solid State Drive",summary:"Focus on flash behavior, TRIM, and why deleted-data recovery is conditional.",topics:["2.7","4.6"]},{title:"10. A Critical Analysis of the Dark Side of the Dark Web",summary:"Evaluate dark-web evidence and investigative boundaries without equating anonymity with crime.",topics:["3.6"]},{title:"11. Tools and Protocols for the Analysis of Mobile Phones",summary:"Compare mobile extraction methods, application formats, and tool limitations.",topics:["3.10","4.3"]},{title:"12. Tree-Based Machine Learning for Credit Card Fraud Detection",summary:"Examine classification, class imbalance, and the operational cost of false positives.",topics:["5.9","5.11"]},{title:"13. Black Hats: A Major Threat to Your Finances",summary:"Connect financial cybercrime patterns with victim protection and payment verification.",topics:["1.5","3.11"]},{title:"14. Enhanced Security Based on Face Detection in Payment Gateway",summary:"Study biometric authentication as a control, including error and spoofing considerations.",topics:["5.7","5.8"]},{title:"15. Artificial Intelligence Applied to Computer Forensics",summary:"Assess assistance, validation, explainability, and the examiner’s continuing responsibility.",topics:["5.10","5.11"]},{title:"16. OAuth 2.0 Defenses and Working Using Digital Signatures",summary:"Distinguish authorization from authentication and examine trust boundaries in token-based systems.",topics:["3.12","5.3"]},{title:"17. Child Pornography: The Filth of Society",summary:"Approach the legal and safeguarding context with victim-centered handling. This course contains no exploitative material or acquisition guidance.",topics:["1.6","2.12"]},{title:"18. Digital Forensics and Cybersecurity Tools",summary:"Create a task-based tool inventory and evaluate versions, validation, and reporting needs.",topics:["4.1","4.2","4.9"]}]},{id:"benild",title:"Digital Crime Investigation",authors:"Benild Joseph",publisher:"Independent publication",year:"2017",color:"blue",code:"THE INVESTIGATOR’S HANDBOOK",url:"https://books.google.com/books/about/Digital_Crime_Investigation.html?id=gi1MDwAAQBAJ",description:"A compact introduction to internet crime, online evidence, IP tracing, email attacks, phishing, and the Indian legal context at the time of publication.",editionNote:"A public, complete publisher chapter listing was not verified. The eight sections below are an original thematic reading route, not a claimed exact table of contents. Match them to the headings in your copy and replace pre-2024 legal references.",chapters:[{title:"Study route 1 · Conventional and cybercrime",summary:"Identify how familiar offences acquire a digital component and define the conduct precisely.",topics:["1.4","1.5"]},{title:"Study route 2 · The range of cyber offences and actors",summary:"Separate roles, capabilities, and motivations from the legal elements of an offence.",topics:["1.5","5.1"]},{title:"Study route 3 · Web-based email attacks and phishing",summary:"Practise header interpretation, message preservation, and independent payment verification.",topics:["3.11"]},{title:"Study route 4 · Collecting and documenting online evidence",summary:"Build a source, capture, integrity, and custody record that another examiner can follow.",topics:["2.6","2.8","2.11"]},{title:"Study route 5 · IP addresses and online tracing",summary:"Understand what an address can show, and where NAT, proxies, and provider records limit attribution.",topics:["2.5","3.9"]},{title:"Study route 6 · The forensic toolkit",summary:"Choose tools for acquisition and examination, and record versions, settings, and limitations.",topics:["4.1","4.2","4.3"]},{title:"Study route 7 · Indian cybercrime law and intermediaries",summary:"Read the historical discussion alongside the current IT Rules and the BNS, BNSS, and BSA. Do not reuse old section numbers automatically.",topics:["1.6","1.7","1.10"]},{title:"Study route 8 · From investigation to presentation",summary:"Connect technical findings to a clear report and the applicable electronic-evidence certification process.",topics:["2.10","4.9","4.12"]}]},{id:"casey",title:"Digital Evidence and Computer Crime",authors:"Eoghan Casey",publisher:"Academic Press / Elsevier",year:"3rd edition · 2011",color:"slate",code:"EVIDENCE / SCIENTIFIC METHOD",url:"https://shop.elsevier.com/books/digital-evidence-and-computer-crime/casey/978-0-08-092148-8",description:"A foundational text on forensic science, digital investigation, offender analysis, and network evidence. Especially valuable for learning to reason from artifacts rather than merely operate software.",editionNote:"The route below follows the third edition’s verified early chapters and major subject areas; it is not a complete publisher TOC. The US and European legal chapters require current Indian-law supplementation.",chapters:[{title:"1. Foundations of Digital Forensics",summary:"Define digital evidence, core principles, the cybertrail, and the challenges of applying forensic science to changing technology.",topics:["2.4","3.7"]},{title:"2. Language of Computer Crime Investigation",summary:"Build a precise vocabulary for systems, roles, and the relationship between computers and crime.",topics:["1.1","1.5"]},{title:"3. Digital Evidence in the Courtroom",summary:"Study expert duties, admissibility, certainty, circumstantial evidence, and presentation.",topics:["2.9","4.10","4.12"]},{title:"4–5. Cybercrime Law",summary:"Compare the book’s US and European legal discussions, then identify the corresponding Indian questions without assuming equivalence.",topics:["1.3","1.12"]},{title:"6. Conducting Digital Investigations",summary:"Use process models, investigative scaffolding, and the scientific method to organize a case.",topics:["2.2","3.7"]},{title:"7. Handling a Digital Crime Scene",summary:"Study authorization, preparation, survey, and preservation. Apply the concepts through the acquisition simulation.",topics:["2.3","2.6"]},{title:"8. Investigative Reconstruction with Digital Evidence",summary:"Evaluate equivocal artifacts, victimology, scene characteristics, and threshold assessments.",topics:["4.7","4.11"]},{title:"9. Modus Operandi, Motive, and Technology",summary:"Connect modus operandi and motive to technical choices while keeping inference separate from observation.",topics:["3.7","5.3"]},{title:"10. Violent Crime and Digital Evidence",summary:"Examine the role of digital traces in serious-crime reconstruction and the need for careful interpretation.",topics:["2.5","4.11"]},{title:"11. Digital Evidence as Alibi",summary:"Test time-based claims and alternative explanations rather than assuming every account event identifies a person.",topics:["2.4","4.7"]},{title:"Computer-system examination",summary:"Read the operating-system and device chapters relevant to your evidence source. Preserve format, timestamp, and application context.",topics:["3.8","3.10","4.5"]},{title:"Network and internet evidence",summary:"Connect the book’s network-layer discussions to current packet, flow, cloud, and provider evidence. Update older tool assumptions.",topics:["3.9","3.12","4.8"]}]}],c=Object.fromEntries(b.map(a=>[a.id,a]));a.s(["bookMap",0,c,"books",0,b])},74849,a=>{"use strict";var b=a.i(64831);let c={name:"library",size:24,node:[["path",{d:"m16 6 4 14",key:"ji33uf"}],["path",{d:"M12 6v14",key:"1n7gus"}],["path",{d:"M8 8v12",key:"1gg7y9"}],["path",{d:"M4 4v16",key:"6qkkli"}]]};c.node;let d=(0,b.default)(c);a.s(["Library",0,d],74849)},53704,a=>{"use strict";var b=a.i(64831);let c={name:"flask-conical",size:24,node:[["path",{d:"M14 2v6a2 2 0 0 0 .245.96l5.51 10.08A2 2 0 0 1 18 22H6a2 2 0 0 1-1.755-2.96l5.51-10.08A2 2 0 0 0 10 8V2",key:"18mbvz"}],["path",{d:"M6.453 15h11.094",key:"3shlmq"}],["path",{d:"M8.5 2h7",key:"csnxdl"}]]};c.node;let d=(0,b.default)(c);a.s(["FlaskConical",0,d],53704)},35306,a=>{"use strict";a.s(["disclaimer",0,"Educational resources, not legal advice. Verify the official notified text and the law applicable on the date of the incident. Simulations use fictional data; no live systems are accessed.","labs",0,[{id:"acquisition",title:"Your first digital crime scene",subtitle:"Preserve first. Investigate second.",minutes:20,unit:2,type:"acquisition",skills:["Evidence handling","Chain of custody","Decision-making"],description:"A laptop, a suspicious invoice, and a running system. Make five decisions that determine whether your evidence survives scrutiny.",steps:["Read the scene and identify volatile evidence.","Confirm the scope of lawful authority.","Choose a proportionate preservation strategy.","Document the device and acquisition.","Complete a defensible custody record."]},{id:"hash",title:"One bit. A different story.",subtitle:"Explore the fingerprint of digital evidence.",minutes:12,unit:4,type:"hash",skills:["SHA-256","Integrity verification","Disk imaging"],description:"Hash a fictional invoice, change a single character, and see why integrity verification is indispensable. All calculations happen in your browser.",steps:["Read the original evidence text.","Calculate its SHA-256 digest.","Alter one character and calculate again.","Compare the fingerprints and explain the limits."]},{id:"osint",title:"The account behind the account",subtitle:"Connect public clues without crossing a line.",minutes:18,unit:3,type:"osint",skills:["OSINT","Source evaluation","Attribution"],description:"Work with a completely fictional public-profile dataset. Link an alias to an organization while separating observation, inference, and identity.",steps:["Define the investigation question.","Collect the public profile record.","Corroborate the alias across two sources.","Record confidence and alternative explanations."]},{id:"network",title:"A signal in the noise",subtitle:"Find the pattern. Question the conclusion.",minutes:15,unit:3,type:"network",skills:["Network forensics","Traffic analysis","Timeline reconstruction"],description:"Inspect synthetic network events, distinguish routine updates from suspicious periodic connections, and build a cautious investigative hypothesis.",steps:["Establish a normal traffic baseline.","Filter events by host and destination.","Compare intervals and payload sizes.","Write a finding with an explicit limitation."]},{id:"email",title:"The invoice that wasn’t",subtitle:"An urgent email is not an instruction to pay.",minutes:15,unit:1,type:"email",skills:["Email headers","Phishing","Fraud triage"],description:"An accounts employee receives a changed bank account instruction. Examine the headers and payment clues before deciding what to preserve.",steps:["Inspect the display name and sending domain.","Interpret SPF, DKIM, and DMARC results.","Separate authentication from legitimacy.","Plan preservation and out-of-band verification."]},{id:"certificate",title:"Make your evidence court-ready",subtitle:"Build a section 63 certificate worksheet.",minutes:18,unit:2,type:"certificate",skills:["BSA section 63","Certification","Evidence presentation"],description:"Prepare Part A and Part B of a fictional electronic-evidence certificate. Understand the source, lawful control, device particulars, hash, and signatories.",steps:["Identify the electronic record and its source.","Complete the party’s worksheet.","Add the expert and hash particulars.","Review and print the training document."]},{id:"ai",title:"Can you trust the alert?",subtitle:"Tune a model. Understand the trade-off.",minutes:15,unit:5,type:"ai",skills:["Machine learning","Precision & recall","Human review"],description:"Adjust a synthetic classifier’s decision threshold. Watch precision, recall, and false positives change, then decide how to triage alerts without treating a score as proof.",steps:["Inspect the synthetic validation dataset.","Adjust the classification threshold.","Read the confusion matrix and performance chart.","Choose a human-review policy and explain its limits."]}],"units",0,[{id:1,roman:"I",title:"Introduction to Cyber Law and Cyber Crime",shortTitle:"Cyber law & cyber crime",description:"Understand the digital world—and the rules that govern it.",color:"blue",icon:"Scale"},{id:2,roman:"II",title:"Cyber Crime Investigation and Electronic Evidence",shortTitle:"Investigation & electronic evidence",description:"Turn digital traces into reliable, admissible evidence.",color:"teal",icon:"Fingerprint"},{id:3,roman:"III",title:"Cyber Investigation Techniques and Digital Forensics",shortTitle:"Investigation & digital forensics",description:"Follow the evidence across devices, networks, and the web.",color:"purple",icon:"ScanSearch"},{id:4,roman:"IV",title:"Digital Forensic Tools and Evidence Presentation",shortTitle:"Forensic tools & evidence",description:"Acquire, examine, and explain evidence with confidence.",color:"orange",icon:"HardDrive"},{id:5,roman:"V",title:"Cyber Threat Intelligence, Cyber Warfare and AI Forensics",shortTitle:"Threat intelligence & AI forensics",description:"Connect emerging threats with intelligent investigation.",color:"rose",icon:"BrainCircuit"}]])},58983,a=>{"use strict";var b=a.i(64831);let c={name:"loader-circle",size:24,node:[["path",{d:"M21 12a9 9 0 1 1-6.219-8.56",key:"13zald"}]],aliases:["loader-2"]};c.node;let d=(0,b.default)(c);a.s(["LoaderCircle",0,d],58983)},9646,a=>{"use strict";var b=a.i(64831);let c={name:"graduation-cap",size:24,node:[["path",{d:"M21.42 10.922a1 1 0 0 0-.019-1.838L12.83 5.18a2 2 0 0 0-1.66 0L2.6 9.08a1 1 0 0 0 0 1.832l8.57 3.908a2 2 0 0 0 1.66 0z",key:"j76jl0"}],["path",{d:"M22 10v6",key:"1lu8f3"}],["path",{d:"M6 12.5V16a6 3 0 0 0 12 0v-3.5",key:"1r8lef"}]]};c.node;let d=(0,b.default)(c);a.s(["GraduationCap",0,d],9646)},19796,a=>{"use strict";var b=a.i(64831);let c={name:"clipboard-check",size:24,node:[["rect",{width:"8",height:"4",x:"8",y:"2",rx:"1",ry:"1",key:"tgr4d6"}],["path",{d:"M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2",key:"116196"}],["path",{d:"m9 14 2 2 4-4",key:"df797q"}]]};c.node;let d=(0,b.default)(c);a.s(["ClipboardCheck",0,d],19796)}];

